/* ---------------------------------------------------------------------------
   Reading the register.

   Edits made in Settings are kept in this browser and win over the shipped
   rows above, so someone can correct a phone number without a redeploy. The
   file stays the source of truth for anyone opening the app fresh.
--------------------------------------------------------------------------- */
const STATE_OVERRIDE_KEY = 'variationCoverSheet:stateRegister';

const StateRegister = (() => {
  const FIELDS = ['code','name','entity','abn','acn','phone','address','email','logo','brand','intro','closing'];

  function readOverrides(){
    try {
      const raw = localStorage.getItem(STATE_OVERRIDE_KEY);
      if(!raw) return null;
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : null;
    } catch(e){ return null; }
  }

  // Overrides are merged row by row rather than swapped in wholesale, so a
  // state added to this file later still appears for someone whose browser is
  // holding an older saved copy.
  function rows(){
    const overrides = readOverrides() || [];
    const byCode = {};
    overrides.forEach(row => { if(row && row.code) byCode[row.code] = row; });
    return STATE_REGISTER.map(base => {
      const over = byCode[base.code];
      if(!over) return Object.assign({}, base);
      const merged = Object.assign({}, base);
      FIELDS.forEach(f => { if(over[f] !== undefined) merged[f] = over[f]; });
      return merged;
    });
  }

  function get(code){
    if(!code) return null;
    return rows().find(r => r.code === code) || null;
  }

  // A row with no entity name has not been filled in yet: the picker greys it
  // out rather than letting someone issue a letter with a blank letterhead.
  function isConfigured(row){
    return !!(row && String(row.entity || '').trim());
  }

  function save(edited){
    try { localStorage.setItem(STATE_OVERRIDE_KEY, JSON.stringify(edited)); return true; }
    catch(e){ return false; }
  }

  function clear(){
    try { localStorage.removeItem(STATE_OVERRIDE_KEY); } catch(e){}
  }

  function hasOverrides(){ return !!readOverrides(); }

  // Rebuilds this file from the current rows, so a browser edit can be
  // committed back to the repo instead of living in one person's cache.
  function toFileSource(){
    const body = rows().map(r => {
      const lines = FIELDS.map(f => {
        const value = r[f] === undefined ? '' : String(r[f]);
        if(f === 'intro' && value === DEFAULT_INTRO) return '    intro: DEFAULT_INTRO';
        if(f === 'closing' && value === DEFAULT_CLOSING) return '    closing: DEFAULT_CLOSING';
        return '    ' + f + ': ' + JSON.stringify(value);
      });
      return '  {\n' + lines.join(',\n') + '\n  }';
    }).join(',\n');
    return 'const STATE_REGISTER = [\n' + body + '\n];\n';
  }

  return { rows, get, isConfigured, save, clear, hasOverrides, toFileSource, FIELDS };
})();
